import { localizeKmMessages } from "./km-messages"
import type { Locale } from "./routing"

let km: Promise<typeof import("@/messages/km").default> | undefined

/**
 * The messages for a locale: src/messages/<locale>/index.ts merges one JSON file per namespace
 * (src/messages/<locale>/<namespace>.json, index generated by `npm run i18n:index`). The Khmer ones are rewritten
 * once so that numbers filled into them print with Khmer digits (km-messages.ts).
 */
export async function loadMessages(locale: Locale) {
  if (locale !== "km") return (await import("@/messages/en")).default
  km ??= import("@/messages/km").then((m) => localizeKmMessages(m.default))
  return km
}
